{"implementation":"def solve(case):
    if not isinstance(case, dict) or 'payload' not in case:
        raise ValueError('Invalid case')
    payload = case['payload']
    if not isinstance(payload, dict):
        raise ValueError('Invalid payload')
    text = payload.get('text')
    if not isinstance(text, str):
        raise ValueError('text must be string')
    passes = payload.get('passes')
    if not isinstance(passes, list):
        raise ValueError('passes must be list')
    max_rounds = payload.get('max_rounds')
    if not isinstance(max_rounds, int) or max_rounds < 0:
        raise ValueError('max_rounds must be non-negative integer')
    current = text
    trace = []
    changed = False
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            name = p.get('name')
            old = p.get('old')
            new = p.get('new')
            if not all(isinstance(x, str) for x in (name, old, new)):
                raise ValueError('Pass fields must be strings')
            idx = current.find(old)
            if idx != -1:
                current = current[:idx] + new + current[idx+len(old):]
                trace.append(name)
                changed = True
        if not changed:
            break
    fixed_point = not changed
    return {'artifact': current, 'trace': trace, 'fixed_point': fixed_point}"}
